SFR_D = SFR_D or {}
SFR_D.sdesc = {
-- v0.6.0: duplicate buckets merged (a Lua table constructor keeps only the last duplicate key, so earlier models were lost)
-- and unreachable models moved to their bucket. Batches: paladin (collected in game, exact match), v0.4.x, warrior (v0.4.2),
-- mage+priest+druid (v0.5.0); wordings of the server Spell.dbc, French text written for this project (UNOFFICIAL).
[""]={{p={"Absorbs "," physical damage, draining mana instead.  Drains "," mana per damage absorbed.  Lasts ","."},f="Absorbe {1} points de dégâts physiques en drainant du mana à la place. Draine {2} points de mana par point de dégât absorbé. Dure {3}."},
{p={"Removes "," "," curse:lesser curses; from a friendly target."},f="Dissipe {1} moindre malédiction(s) d'une cible alliée."},
{p={"Conjures "," "," of water, providing the mage and "," allies with something to drink.\n\nConjured items disappear if logged out for more than 15 minutes."},f="Invoque {1} bouteille(s) d'eau, donnant au mage et à ses alliés de quoi boire.\n  \n Les objets invoqués disparaissent après une déconnexion de plus de 15 minutes."},
{p={"Conjures "," ",", providing the mage and "," allies with something to eat.\n\nConjured items disappear if logged out for more than 15 minutes."},f="Invoque {1} muffin(s), donnant au mage et à ses alliés de quoi manger.\n  \n Les objets invoqués disparaissent après une déconnexion de plus de 15 minutes."},
{p={"Removes "," "," from the friendly target."},f="Retire {1} maladie(s) de la cible alliée."},
{p={"Causes "," Arcane damage to the target."},f="Inflige {1} points de dégâts des arcanes à la cible."},
{p={"Cures "," poison "," on the target."},f="Guérit {1} effet(s) de poison sur la cible."},
{p={"Dispels "," curse from the target."},f="Dissipe {1} malédiction de la cible."},
{p={"Swipe "," nearby enemies, inflicting "," damage."},f="Balaye {1} ennemis proches, leur infligeant {2} points de dégâts."},
{p={"","% of the threat generated by your totems is transferred to you."},f="{1}% de la menace générée par vos totems vous est transférée."},
{p={"Generates 10% of your maximum mana over 5 sec."},f="Génère 10% de votre mana maximum sur 5 sec."},
{p={"Sends bolts of holy power in all directions, causing 490 to 576 Holy damage to all Undead and Demon targets within 20 yds."},f="Envoie des éclairs de puissance sacrée dans toutes les directions, infligeant 490 à 576 points de dégâts sacrés à toutes les cibles morts-vivants et démons dans un rayon de 20 m."},
{p={"Increases Holy damage done by party members within 30 yards by 10%.  Players may only have one Aura on them per Paladin at any one time."},f="Augmente les dégâts sacrés infligés par les membres du groupe à moins de 30 mètres de 10%. Les joueurs ne peuvent avoir qu'une seule Aura par paladin à la fois."},
{p={"Equip: Your Consecration heals party members for 120 over 8 sec. and grants them 5 Strength while inside it."},f="Équipé : Votre Consécration soigne les membres du groupe de 120 points sur 8 sec. et leur accorde 5 en Force tant qu'ils s'y trouvent."},
{p={"Strikes the target for Holy damage, dealing 40% weapon damage plus an additional 129 to 146, and restores 90 health and 90 mana to you and up to 4 allies within 10 yards. Healing on yourself is reduced by half."},f="Frappe la cible de dégâts sacrés, infligeant 40% des dégâts d'arme plus 129 à 146 supplémentaires, et restaure 90 points de vie et 90 points de mana à vous et à 4 alliés proches. Les soins sur vous-même sont réduits de moitié."},
{p={"Use: Restores 1350 to 2250 mana. CD: 2.0 min"},f="Utiliser : Rend 1350 à 2250 points de mana. Recharge : 2,0 min"},
{p={"Skill with Maces and Two-Handed Maces increased by 5."},f="Compétence avec les masses et les masses à deux mains augmentée de 5."},
{p={"Increases the melee attack power bonus of your Seal of the Crusader and the Holy damage increase of your Judgement of the Crusader by 15%."},f="Augmente de 15% le bonus de puissance d'attaque de votre Sceau de croisé et l'augmentation de dégâts sacrés de votre Jugement du croisé."},
{p={"Consecrates the land beneath the Paladin, inflicting 72 Holy damage over 8 sec to enemies within the area. The consecrated power wanes, dealing reduced damage as time passes."},f="Consacre le sol sous le paladin, infligeant 72 points de dégâts sacrés sur 8 sec aux ennemis de la zone. La puissance consacrée s'affaiblit, infligeant des dégâts réduits avec le temps."},
{p={"Causes 505 to 563 Holy damage to an Undead or Demon target. This spell generates reduced threat."},f="Inflige 505 à 563 points de dégâts sacrés à une cible mort-vivant ou démon. Ce sort génère une menace réduite."},
{p={"Improves your chance to hit with Hand of Reckoning by 4%."},f="Améliore vos chances de toucher avec Main du châtiment de 4%."},
{p={"Increases chance to block by 45% for 10 sec. While active, each blocked attack deals 35 Holy damage to the attacker.  Damage caused by Holy Shield generates 50% additional threat.  Each block expends a charge.  4 charges."},f="Augmente les chances de blocage de 45% pendant 10 sec. Tant que c'est actif, chaque attaque bloquée inflige 35 points de dégâts sacrés à l'attaquant. Les dégâts causés par Bouclier sacré génèrent 50% de menace supplémentaire. Chaque blocage consomme une charge. 4 charges."},
{p={"Cleanses a friendly target, removing 1 poison effect, 1 disease effect, and 1 magic effect."},f="Purifie une cible alliée, retirant 1 effet de poison, 1 effet de maladie et 1 effet magique."},
{p={"Gives 60 additional Shadow resistance to all party members within 30 yards.  Players may only have one Aura on them per Paladin at any one time."},f="Donne 60 points de résistance à l'ombre supplémentaires à tous les membres du groupe à moins de 30 mètres. Les joueurs ne peuvent avoir qu'une seule Aura par paladin à la fois."},
{p={"Increases the amount healed by your Holy Light, Flash of Light and Holy Shock spells by 4%."},f="Augmente les quantités soignées par vos sorts Lumière sacrée, Éclair de lumière et Choc sacré de 4%."},
{p={"Crusader Strike deals an additional 10% damage and Zeal increases your attack and casting speed by an additional 2% per stack.\nHoly Strike infuses you with Holy Might, increasing your Strength by 20% for 20 sec."},f="Frappe du croisé inflige 10% de dégâts supplémentaires et Zèle augmente votre vitesse d'attaque et d'incantation de 2% supplémentaires par cumul.\nFrappe sacrée vous imprègne de Puissance sacrée, augmentant votre Force de 20% pendant 20 sec."},
{p={"Reduces the mana cost of your spells by 20% inside Battlegrounds and Arenas."},f="Réduit le coût en mana de vos sorts de 20% dans les champs de bataille et les arènes."},
{p={"The targeted undead enemy will be compelled to flee for up to 20 sec.  Damage caused may interrupt the effect.  Only one target can be turned at a time."},f="Le mort-vivant ciblé sera contraint de fuir pendant au maximum 20 sec. Les dégâts causés peuvent interrompre l'effet. Une seule cible peut être repoussée à la fois."},
{p={"While Righteous Fury is active, your damage taken is reduced by 3%."},f="Tant que Fureur vertueuse est active, les dégâts que vous subissez sont réduits de 3%."},
{p={"Increases your armor value from items by 2%."},f="Augmente la valeur d'armure de vos objets de 2%."},
{p={"Consecrates the land beneath the Paladin, inflicting 432 Holy damage over 8 sec to enemies within the area. The consecrated power wanes, dealing reduced damage as time passes."},f="Consacre le sol sous le paladin, infligeant 432 points de dégâts sacrés sur 8 sec aux ennemis de la zone. La puissance consacrée s'affaiblit, infligeant des dégâts réduits avec le temps."},
{p={"Improves your chance to get a critical strike with Holy Shock by 10%."},f="Améliore vos chances d'infliger un coup critique avec Choc sacré de 10%."},
{p={"Increases healing done by spells and effects by up to 1% of your Armor from items."},f="Augmente les soins des sorts et effets de jusqu'à 1% de l'armure de vos objets."},
{p={"Use: Restores 525 to 875 health and 810 to 1350 mana. CD: 2.0 min"},f="Utiliser : Rend 525 à 875 points de vie et 810 à 1350 points de mana. Recharge : 2,0 min"},
{p={"Unleashes the energy of a Seal spell upon an enemy.  Refer to individual Seals for Judgement effect."},f="Libère l'énergie d'un sceau sur un ennemi. Consultez chaque sceau pour connaître l'effet de Jugement."},
{p={"Increases the effect of your Concentration Aura by an additional 5% and gives all group members affected by the aura an additional 5% chance to resist Silence and Interrupt effects."},f="Augmente l'effet de votre Aura de concentration de 5% supplémentaires et donne à tous les membres du groupe affectés par l'aura 5% de chances supplémentaires de résister aux effets de silence et d'interruption."},
{p={"Taunts the target to attack you, but has no effect if the target is already attacking you."},f="Provoque la cible pour qu'elle vous attaque, mais n'a aucun effet si elle vous attaque déjà."},
{p={"Places a Blessing on the friendly target, reducing damage taken from all sources by up to 10 for 10 min.  In addition, when the target blocks a melee attack, the attacker takes 14 Holy damage.  Players may only have one Blessing on them per Paladin at any one time."},f="Place une Bénédiction sur la cible alliée, réduisant les dégâts subis de toutes sources de jusqu'à 10 pendant 10 min. De plus, quand la cible bloque une attaque de mêlée, l'attaquant subit 14 points de dégâts sacrés. Les joueurs ne peuvent avoir qu'une seule Bénédiction par paladin à la fois."},
{p={"Unpack the Goblin Brainwashing Device so that it can reset specialization points. It only has enough power to last for 5 min."},f="Déballe la Machine de lavage de cerveau gobeline pour réinitialiser vos points de spécialisation. Sa puissance ne dure que 5 min."},
{p={"Gives a 35% chance of ignoring spell interruption when damaged to all party members within 30 yards.  Players may only have one Aura on them per Paladin at any one time."},f="Donne à tous les membres du groupe à moins de 30 mètres 35% de chances d'ignorer l'interruption des sorts quand ils subissent des dégâts. Les joueurs ne peuvent avoir qu'une seule Aura par paladin à la fois."},
{p={"Increases the amount of damage absorbed by your shield by 10% and has a 33% chance to restore 2% of maximum mana when a block occurs. This effect cannot occur more than once every 5 sec."},f="Augmente les dégâts absorbés par votre bouclier de 10% et a 33% de chances de restaurer 2% du mana maximum lorsqu'un blocage se produit. Cet effet ne peut se produire qu'une fois toutes les 5 sec."},
{p={"Increases the armor bonus of your Devotion Aura by 5%."},f="Augmente le bonus d'armure de votre Aura de dévotion de 5%."},
{p={"Increases the critical effect chance of your Holy Light and Flash of Light by 2%."},f="Augmente les chances de coup critique de vos sorts Lumière sacrée et Éclair de lumière de 2%."},
{p={"Successful melee and ranged attacks against you have a 2% chance to increase your chance to block by 3%. Lasts 10 sec or 5 blocks."},f="Les attaques de mêlée et à distance réussies contre vous ont 2% de chances d'augmenter vos chances de blocage de 3%. Dure 10 sec. ou 5 blocages."},
{p={"Fills the Paladin with divine light for 30 sec, giving each melee attack a chance to heal the Paladin for 76.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, granting melee attacks made against the judged enemy a chance of healing the attacker for 49.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time."},f="Remplit le paladin de lumière divine pendant 30 sec, donnant à chaque attaque de mêlée une chance de soigner le paladin de 76. Un seul sceau peut être actif sur le paladin à la fois.\n\nLibérer l'énergie de ce sceau jugera un ennemi pendant 10 sec, donnant aux attaques de mêlée portées contre l'ennemi jugé une chance de soigner l'attaquant de 49. Vos frappes en mêlée rafraîchiront la durée du sort. Un seul Jugement par paladin peut être actif à la fois."},
{p={"Gives the Paladin's damaging melee attacks a chance to reduce the target's damage dealt by 9% for 10 sec. Only affects targets of level 62 or lower. Chance: 40%"},f="Donne aux attaques de mêlée du paladin une chance de réduire les dégâts infligés par la cible de 9% pendant 10 sec. N'affecte que les cibles de niveau 62 ou moins. Chance : 40%"},
{p={"Use: Restores 700 to 900 health. CD: 2.0 min"},f="Utiliser : Rend 700 à 900 points de vie. Recharge : 2,0 min"},
{p={"Gives 60 additional Frost resistance to all party members within 30 yards.  Players may only have one Aura on them per Paladin at any one time."},f="Donne 60 points de résistance au givre supplémentaires à tous les membres du groupe à moins de 30 mètres. Les joueurs ne peuvent avoir qu'une seule Aura par paladin à la fois."},
{p={"A strike that deals 110% weapon damage plus an additional 177 to 178 and increases your attack speed by 5%.  Stacks up to 3 times.  Lasts 30 sec."},f="Une frappe qui inflige 110% des dégâts d'arme plus 177 à 178 supplémentaires et augmente votre vitesse d'attaque de 5%. Se cumule jusqu'à 3 fois. Dure 30 sec."},
{p={"Places a Blessing on the friendly target, increasing melee attack power by 185 for 10 min.  Players may only have one Blessing on them per Paladin at any one time."},f="Place une Bénédiction sur la cible alliée, augmentant la puissance d'attaque en mêlée de 185 pendant 10 min. Les joueurs ne peuvent avoir qu'une seule Bénédiction par paladin à la fois."},
{p={"Increases your chance to resist Fear and Disorient effects by an additional 10%."},f="Augmente vos chances de résister aux effets de peur et de désorientation de 10% supplémentaires."},
{p={"Brings a dead player back to life with 400 health and 600 mana.  Cannot be cast when in combat."},f="Rend la vie à un joueur mort avec 400 points de vie et 600 points de mana. Incantable en combat."},
{p={"A targeted party member is protected from all physical attacks for 10 sec, but during that time they cannot attack or use physical abilities.  Players may only have one Hand on them per Paladin at any one time.  Once protected, the target cannot be made invulnerable by Divine Shield, Divine Protection or Blessing of Protection again for 1 min."},f="Un membre du groupe ciblé est protégé de toutes les attaques physiques pendant 10 sec, mais pendant ce temps il ne peut ni attaquer ni utiliser de capacités physiques. Les joueurs ne peuvent avoir qu'une seule Main par paladin à la fois. Une fois protégée, la cible ne peut plus être rendue invulnérable par Bouclier divin, Protection divine ou Bénédiction de protection avant 1 min."},
{p={"Protects the paladin from all damage and spells for 12 sec, but decreases the damage you deal with all attacks and spells by 60%.  Once protected, the target cannot be made invulnerable by Divine Shield, Divine Protection or Blessing of Protection again for 1 min."},f="Protège le paladin de tous les dégâts et sorts pendant 12 sec, mais réduit les dégâts de toutes vos attaques et sorts de 60%. Une fois protégé, la cible ne peut plus être rendue invulnérable par Bouclier divin, Protection divine ou Bénédiction de protection avant 1 min."},
{p={"Places a Blessing on the friendly target, increasing total stats by 10% for 10 min.  Players may only have one Blessing on them per Paladin at any one time."},f="Place une Bénédiction sur la cible alliée, augmentant toutes les caractéristiques de 10% pendant 10 min. Les joueurs ne peuvent avoir qu'une seule Bénédiction par paladin à la fois."},
{p={"Increases the damage done by your Seal of Righteousness and Judgement of Righteousness by 2%."},f="Augmente les dégâts de votre Sceau de vertu et de votre Jugement de vertu de 2%."},
{p={"Fills the Paladin with the spirit of a crusader for 30 sec, granting 429 melee attack power.  The Paladin also attacks 40% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, increasing Holy damage taken by up to 221.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time."},f="Remplit le paladin de l'esprit d'un croisé pendant 30 sec, accordant 429 points de puissance d'attaque. Le paladin attaque aussi 40% plus vite, mais inflige moins de dégâts à chaque attaque. Un seul sceau peut être actif sur le paladin à la fois.\n\nLibérer l'énergie de ce sceau jugera un ennemi pendant 10 sec, augmentant les dégâts sacrés subis de jusqu'à 221. Vos frappes en mêlée rafraîchiront la durée du sort. Un seul Jugement par paladin peut être actif à la fois."},
{p={"Reduces the Mana cost of your Judgement and Seal spells by 15%."},f="Réduit le coût en mana de vos sorts Jugement et Sceau de 15%."},
{p={"Increases movement and mounted movement speed by 8%.  This does not stack with other movement speed increasing effects."},f="Augmente la vitesse de déplacement et de déplacement monté de 8%. Ne se cumule pas avec les autres effets augmentant la vitesse de déplacement."},
{p={"Increases your chance to get a critical strike with melee weapons by 5%."},f="Augmente vos chances d'infliger un coup critique avec les armes de mêlée de 5%."},
{p={"Increases the damage done by your Retribution Aura by 25%."},f="Augmente les dégâts infligés par votre Aura de vindicte de 25%."},
{p={"Increases the amount of threat generated by your Righteous Fury spell by 25%."},f="Augmente la menace générée par votre sort Fureur vertueuse de 25%."},
{p={"Places a Blessing on the friendly target, granting immunity to movement impairing effects for 10 sec.  Players may only have one Hand on them per Paladin at any one time."},f="Place une Bénédiction sur la cible alliée, lui accordant une immunité aux effets entravant le déplacement pendant 10 sec. Les joueurs ne peuvent avoir qu'une seule Main par paladin à la fois."},
{p={"Use: Restores 900 to 1500 mana at the cost of 600 to 1000 life. CD: 2.0 min"},f="Utiliser : Rend 900 à 1500 points de mana au prix de 600 à 1000 points de vie. Recharge : 2,0 min"},
{p={"Increases the effectiveness your Blessing of Might and Wisdom by 4%."},f="Augmente l'efficacité de vos bénédictions Bénédiction de puissance et Bénédiction de sagesse de 4%."},
{p={"Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec.  Any damage caused will awaken the target.\n\nIf the target is immune to the effect, they repent for their sins, taking 80 Holy damage each time they perform a melee attack for 20 sec."},f="Place la cible ennemie en état de méditation, l'incapacitant pendant 6 sec. Tout dégât causé réveille la cible.\n\nSi la cible est immunisée contre l'effet, elle expie ses péchés, subissant 80 points de dégâts sacrés à chaque attaque de mêlée pendant 20 sec."},
{p={"Gives your Flash of Light and Holy Light spells a 70% chance to not lose casting time when you take damage."},f="Donne à vos sorts Éclair de lumière et Lumière sacrée 70% de chances de ne pas perdre de temps d'incantation quand vous subissez des dégâts."},
{p={"Hurls a hammer that strikes an enemy for 412 to 455 Holy damage.  Only usable on enemies that have 20% or less health."},f="Lance un marteau frappant un ennemi, lui infligeant 412 à 455 points de dégâts sacrés. Utilisable uniquement sur les ennemis ayant 20% de points de vie ou moins."},
{p={"Reduces the cooldown of your Hand of Protection by 60 sec and increases the duration of your Hand of Freedom by 3 sec."},f="Réduit le temps de recharge de votre Main de protection de 60 sec et augmente la durée de votre Main de liberté de 3 sec."},
{p={"Increases your chance to hit with melee attacks and spells by 1%."},f="Augmente vos chances de toucher avec les attaques de mêlée et les sorts de 1%."},
{p={"Equip: Increases healing done by Flash of Light by 28."},f="Équipé : Augmente les soins de l'Éclair de lumière de 28."},
{p={"Fills the Paladin with divine wisdom for 30 sec, giving each melee attack a chance to restore 187 of the Paladin's mana.  Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, granting attacks and spells used against the judged enemy a chance to restore 59 mana to the attacker.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time."},f="Remplit le paladin de sagesse divine pendant 30 sec, donnant à chaque attaque de mêlée une chance de restaurer 187 points de mana du paladin. Un seul sceau peut être actif sur le paladin à la fois.\n\nLibérer l'énergie de ce sceau jugera un ennemi pendant 10 sec, donnant aux attaques et sorts portés contre l'ennemi jugé une chance de restaurer 59 points de mana à l'attaquant. Vos frappes en mêlée rafraîchiront la durée du sort. Un seul Jugement par paladin peut être actif à la fois."},
{p={"Increases the threat generated by your Holy Strike by 5% and its damage by 5%. In addition, Crusader Strike grants Zealous Defense, causing the next successful block to prevent an additional 6% of the attack's damage."},f="Augmente la menace générée par votre Frappe sacrée de 5% et ses dégâts de 5%. De plus, Frappe du croisé accorde Défense zélée : le prochain blocage réussi prévient 6% supplémentaires des dégâts de l'attaque."},
{p={"Skill with Swords and Two-Handed Swords increased by 5."},f="Compétence avec les épées et les épées à deux mains augmentée de 5."},
{p={"Increases the damage you deal with two-handed melee weapons by 6%, and your weapon skill with two-handed swords, maces and axes by 3."},f="Augmente les dégâts infligés avec les armes de mêlée à deux mains de 6%, et votre compétence d'arme avec les épées, masses et haches à deux mains de 3."},
{p={"Gives 60 additional Fire resistance to all party members within 30 yards.  Players may only have one Aura on them per Paladin at any one time."},f="Donne 60 points de résistance au feu supplémentaires à tous les membres du groupe à moins de 30 mètres. Les joueurs ne peuvent avoir qu'une seule Aura par paladin à la fois."},
{p={"Nearby harvestable trees appear on the minimap.  Only one type of thing can be tracked at a time."},f="Les arbres récoltables proches apparaissent sur la minimap. Un seul type d'élément peut être suivi à la fois."},
{p={"Increases the threat generated by your Holy attacks by 60%.  Lasts until cancelled."},f="Augmente la menace générée par vos attaques sacrées de 60%. Dure jusqu'à annulation."},
{p={"Causes 20 Holy damage to any creature that strikes a party member within 30 yards.  Players may only have one Aura on them per Paladin at any one time."},f="Inflige 20 points de dégâts sacrés à toute créature frappant un membre du groupe à moins de 30 mètres. Les joueurs ne peuvent avoir qu'une seule Aura par paladin à la fois."},
{p={"Equip a fishing pole and find a body of water to fish.  Right-Click on the bob in the water when it splashes to catch your fish.  Higher skill increases your chance of fishing successfully in higher level areas."},f="Équipez une canne à pêche et trouvez un plan d'eau pour pêcher. Clic droit sur le flotteur dans l'eau quand il s'agite pour attraper votre poisson. Une compétence plus élevée augmente vos chances de pêcher avec succès dans les zones de plus haut niveau."},
{p={"Adds ","% of your Stamina to your pets' Stamina and increases their health by ","%."},f="Ajoute {1}% de votre Endurance à l'Endurance de vos familiers et augmente leur santé de {2}%."},
{p={"Adds ","% of your armor value from items to the armor value of your pets and increases the armor value of your pets by ","%."},f="Ajoute {1}% de votre valeur d'armure provenant des objets à la valeur d'armure de vos familiers et augmente leur valeur d'armure de {2}%."},
{p={"Allows ","% of your Mana regeneration to continue while casting."},f="Permet à {1}% de votre récupération de mana de continuer pendant l'incantation."},
{p={"Allows ","% of your Mana regeneration to continue while casting. This effect is tripled while below ","% total mana."},f="Permet à {1}% de votre récupération de mana de continuer pendant l'incantation. Cet effet est triplé lorsque votre mana total est inférieur à {2}%."},
{p={"Deals "," damage and stuns the opponent for ",". This ability deals a high amount of threat and penetrates ","% of the enemy's armor. Instantly generates "," rage."},f="Inflige {1} dégâts et étourdit l'adversaire pendant {2}. Cette capacité génère beaucoup de menace et ignore {3}% de l'armure de l'ennemi. Génère instantanément {4} points de rage."},
{p={"Gives a ","% chance to remove all movement impairing effects when you activate your Sprint ability."},f="Vous donne {1}% de chances de supprimer tous les effets entravant le déplacement lorsque vous activez votre capacité Sprint."},
{p={"Inflicts ","% weapon damage and leaves the target wounded, reducing the effectiveness of any healing by ","% for ","."},f="Inflige {1}% des dégâts d'arme et laisse la cible blessée, réduisant l'efficacité de tous les soins de {2}% pendant {3}."},
{p={"Inflicts "," damage to an enemy, stunning it for ","."},f="Inflige {1} points de dégâts à un ennemi et l'étourdit pendant {2}."}},
["A finishin"]={{p={"A finishing move that etches a sigil onto the target for ",". The sigil accumulates damage equal to a percentage of all damage the target takes during its duration, up to a percentage of your Attack Power. When the maximum capacity is reached or the sigil expires, the stored damage is unleashed as Physical damage. Both values increase with each combo point:\n   "," point : ","% of damage accumulated, up to ","% of Attack Power\n   "," points: ","% of damage accumulated, up to ","% of Attack Power\n   "," points: ","% of damage accumulated, up to ","% of Attack Power\n   "," points: ","% of damage accumulated, up to ","% of Attack Power\n   "," points: ","% of damage accumulated, up to ","% of Attack Power"},f="Un coup final qui grave un sceau sur la cible pendant {1}. Le sceau accumule des dégâts égaux à un pourcentage de tous les dégâts subis par la cible pendant sa durée, jusqu'à un pourcentage de votre puissance d'attaque. Lorsque la capacité maximale est atteinte ou que le sceau expire, les dégâts accumulés sont libérés sous forme de dégâts physiques. Les deux valeurs augmentent avec chaque point de combo :\n   {2} point : {3}% des dégâts accumulés, jusqu'à {4}% de la puissance d'attaque\n   {5} points : {6}% des dégâts accumulés, jusqu'à {7}% de la puissance d'attaque\n   {8} points : {9}% des dégâts accumulés, jusqu'à {10}% de la puissance d'attaque\n   {11} points : {12}% des dégâts accumulés, jusqu'à {13}% de la puissance d'attaque\n   {14} points : {15}% des dégâts accumulés, jusqu'à {16}% de la puissance d'attaque"}},
["A precise "]={{p={"A precise shot with a ranged weapon that strikes the target for ","% weapon damage plus an additional "," damage."},f="Un tir précis avec une arme à distance qui inflige {1}% des dégâts de l'arme, plus {2} dégâts supplémentaires."}},
["A short-ra"]={{p={"A short-range shot that deals ","% weapon damage and disorients the target for ",".  Any damage caused will remove the effect.  Turns off your attack when used."},f="Un tir à courte portée qui inflige {1}% des dégâts de l'arme et désoriente la cible pendant {2}. Tous les dégâts subis annulent l'effet. Désactive votre attaque une fois utilisé."}},
["A strike t"]={{p={"A strike that becomes active after parrying an opponent's attack.  This attack deals ","% weapon damage and disarms the target for ","."},f="Une attaque qui devient disponible après avoir paré une attaque adverse. Cette attaque inflige {1}% des dégâts de l'arme et désarme la cible pendant {2}."}},
["A sweeping"]={{p={"A sweeping attack that does your weapon damage plus "," to the target and his nearest ally."},f="Une attaque circulaire qui inflige vos dégâts d'arme plus {1} à la cible et à son plus proche allié."},
{p={"A sweeping attack that does your melee damage plus "," to the target and his nearest ally."},f="Une attaque circulaire qui inflige vos dégâts de mêlée plus {1} à la cible et à son plus proche allié."},
{p={"A sweeping attack that strikes up to "," enemies in a "," yard cone in front of you, dealing ","% weapon damage.\nThis ability shares a cooldown with Multi-Shot."},f="Une attaque circulaire qui frappe jusqu'à {1} ennemis dans un cône de {2} mètres devant vous et inflige {3}% des dégâts de l'arme.\nCette capacité partage son temps de recharge avec Fusillade."}},
["A vicious "]={{p={"A vicious strike that deals ","% weapon damage and wounds the target, reducing the effectiveness of any healing by ","% for ","."},f="Une frappe vicieuse qui inflige {1}% des dégâts d'arme et blesse la cible, réduisant l'efficacité de tous les soins de {2}% pendant {3}."},
{p={"A vicious strike that deals weapon damage plus "," and wounds the target, reducing the effectiveness of any healing by ","% for ","."},f="Une frappe vicieuse qui inflige les dégâts d'arme plus {1} et blesse la cible, réduisant l'efficacité de tous les soins de {2}% pendant {3}."},
{p={"A vicious strike that deals melee damage plus "," and wounds the target, reducing the effectiveness of any healing by ","% for ","."},f="Une frappe vicieuse qui inflige vos dégâts de mêlée plus {1} et blesse la cible, réduisant l'efficacité de tous les soins de {2}% pendant {3}."},
{p={"A vicious strike that deals ","% weapon damage and wounds the target, reducing the effectiveness of any healing by ","% for ","."},f="Une frappe vicieuse qui inflige {1}% des dégâts de l'arme et blesse la cible, réduisant de {2}% l'efficacité de tous les soins qu'elle reçoit pendant {3}."}},
["A wave of "]={{p={"A wave of flame radiates outward from the caster, damaging all enemies caught within the "," yard blast for "," Fire damage, and dazing them for ","."},f="Une vague de flammes se propage à partir du lanceur, infligeant {2} dégâts de Feu à tous les ennemis pris dans l'explosion de {1} mètres et les étourdissant pendant {3}."}},
["Adds a chi"]={{p={"Adds a chill effect to your Blizzard spell.  This effect lowers the target's movement speed by ","%.  Lasts ","."},f="Ajoute un effet de froid à votre sort Blizzard. Cet effet réduit la vitesse de déplacement de la cible de {1}%. Dure {2}."}},
["Adds the f"]={{p={"Adds the following effects to your weapons, based on the weapon type:Axe - Increases your chance to get a critical strike by ","%.Mace - Causes your attacks to ignore "," of your target's Armor per level.Sword - Gives you a ","% chance to get an extra attack on the same target after hitting your target.Polearm - Increases the range of melee attacks by "," yd."},f="Ajoute les effets suivants à vos armes, selon leur type :\nHache - Augmente vos chances d'infliger un coup critique de {1}%.\nMasse - Vos attaques ignorent {2} points de l'armure de la cible par niveau.\nÉpée - Vous donne {3}% de chances d'obtenir une attaque supplémentaire sur la même cible après l'avoir touchée.\nArme d'hast - Augmente la portée des attaques de mêlée de {4} m."}},
["Afflicts y"]={{p={"Afflicts your target with Shadow energy that causes all party members to be healed for ","% of any Shadow spell damage you deal for ","."},f="Frappe votre cible d'énergie d'ombre : tous les membres du groupe sont soignés à hauteur de {1}% des dégâts d'un sort d'Ombre que vous infligez pendant {2}."}},
["After bein"]={{p={"After being struck by a melee or ranged critical hit, heal ","% of the damage taken over ","."},f="Après avoir subi un coup critique de mêlée ou à distance, vous vous soignez de {1}% des dégâts subis pendant {2}."}},
["After gett"]={{p={"After getting a critical effect from your Flash of Light, Holy Light, or Holy Shock heal spell, you regain Mana equal to ","% of the base cost of the spell."},f="Après un effet critique de vos sorts de soins Éclair lumineux, Lumière sacrée ou Horion sacré, vous récupérez un montant de mana égal à {1}% du coût de base du sort."}},
["After heal"]={{p={"After healing a target affected by your Healing Way effect, you have a ","% chance to regain mana equal to ","% of the base cost of the spell."},f="Après avoir soigné une cible affectée par votre effet Voie de guérison, vous avez {1}% de chances de récupérer un montant de mana égal à {2}% du coût de base du sort."}},
["After kill"]={{p={"After killing an opponent that yields experience or honor, gives you a ","% increased critical strike chance on your next Combo Point generating ability.  Lasts ","."},f="Après avoir tué un adversaire qui rapporte de l'expérience ou de l'honneur, vous obtenez {1}% de chances supplémentaires d'infliger un coup critique avec votre prochaine capacité générant des points de combo. Dure {2}."}},
["After land"]={{p={"After landing a critical strike with a Fire, Frost, or Nature damage spell or melee attack, you enter a Clearcasting state.  The Clearcasting state reduces the mana cost of your next two damage spells or abilities by ","%."},f="Après un coup critique avec un sort de Feu, de Givre ou de Nature ou une attaque de mêlée, vous entrez dans un état de Clairvoyance. Cet état réduit de {1}% le coût en mana de vos deux prochains sorts ou capacités de dégâts."}},
["Aligns nat"]={{p={"Aligns natural and astral energies. Damage from Wrath has a ","% chance to grant Arcane Eclipse, increasing Arcane damage dealt. Damage from Starfire has a ","% chance to grant Nature Eclipse, increasing Nature damage dealt.\n\nThe damage bonus is ","% plus ","% of your spell critical strike chance. Each effect lasts "," and has its own "," sec cooldown. Only one Eclipse can be active at a time."},f="Aligne les énergies naturelles et astrales. Les dégâts de Colère ont {1}% de chances d'accorder l'Éclipse des arcanes, augmentant les dégâts des Arcanes infligés. Les dégâts de Feu stellaire ont {2}% de chances d'accorder l'Éclipse de la nature, augmentant les dégâts de Nature infligés.\n\nLe bonus de dégâts est de {3}% plus {4}% de vos chances de coup critique avec les sorts. Chaque effet dure {5} et a son propre temps de recharge de {6} sec. Une seule Éclipse peut être active à la fois."}},
["All spell "]={{p={"All spell criticals against you cause ","% of the damage taken to the caster as well.  The damage caused by Eye for an Eye will not exceed ","% of the Paladin's total health."},f="Tous les coups critiques de sorts contre vous infligent aussi {1}% des dégâts subis au lanceur. Les dégâts causés par Oeil pour oeil ne dépasseront pas {2}% de la santé totale du paladin."},
{p={"All spell criticals grace you with a blessing of nature, reducing the casting time of your next spell by "," sec."},f="Tous les coups critiques de sorts vous accordent une bénédiction de la nature, réduisant de {1} sec le temps d'incantation de votre prochain sort."}},
["An instant"]={{p={"An instant shot that deals ","% weapon damage and attaches bait to the target, causing them to take ","% more damage from your pet. Your pet’s attacks generate "," Focus for ",". Can only be used after your pet critically strikes a target. Focus generation can only occur once every "," sec."},f="Un tir instantané qui inflige {1}% des dégâts de l'arme et fixe un appât à la cible, la faisant subir {2}% de dégâts supplémentaires de votre familier. Les attaques de votre familier génèrent {3} points de Focalisation pendant {4}. Ne peut être utilisé qu'après un coup critique de votre familier sur une cible. La génération de Focalisation ne peut survenir qu'une fois toutes les {5} sec."}},
["Assault th"]={{p={"Assault the target's mind with Shadow energy, causing "," damage over "," and slowing the target to ","% of their movement speed."},f="Assiège l'esprit de la cible d'énergie de l'ombre, lui infligeant {1} points de dégâts sur {2} et réduisant sa vitesse de déplacement à {3}%."},
{p={"Assault the target's mind with Shadow energy, causing "," Shadow damage over "," and slowing their movement speed by ","%."},f="Assaille l'esprit de la cible avec de l'énergie d'ombre, infligeant {1} dégâts d'Ombre pendant {2} et ralentissant sa vitesse de déplacement de {3}%."}},
["Assume a S"]={{p={"Assume a Shadowform, increasing your Shadow damage by ","% and reducing Physical damage done to you by ","%.  However, you may only cast Shadow and Discipline spells while in this form."},f="Prend une forme d'ombre, augmentant vos dégâts de l'ombre de {1}% et réduisant les dégâts physiques subis de {2}%. Cependant, seuls les sorts de l'Ombre et de la Discipline peuvent être lancés sous cette forme."},
{p={"Assume a Shadowform, increasing your Shadow damage by ","% and reducing Physical damage done to you by ","%.  However, you may not cast Holy spells with the exception of Holy Nova while in this form."},f="Vous adoptez une Forme d'ombre, augmentant vos dégâts d'Ombre de {1}% et réduisant de {2}% les dégâts physiques que vous subissez. Cependant, vous ne pouvez pas lancer de sorts Sacrés, à l'exception de Nova sacrée, sous cette forme."}},
["Bash the t"]={{p={"Bash the target with your shield, dealing "," Holy damage and reducing the damage you take by ","% for ","."},f="Frappe la cible avec votre bouclier, infligeant {1} dégâts Sacrés et réduisant de {2}% les dégâts que vous subissez pendant {3}."}},
["Blasts the"]={{p={"Blasts the target for "," shadow damage, but causes a high amount of threat."},f="Frappe la cible, lui infligeant {1} points de dégâts de l'ombre, mais génère une grande quantité de menace."},
{p={"Blasts the target with Holy energy, causing "," Holy damage to an enemy, or "," healing to an ally. Casting Holy Shock has a chance to have no cooldown for its next cast."},f="Frappe la cible d'énergie sacrée, infligeant {1} dégâts Sacrés à un ennemi ou soignant un allié de {2}. Lancer Horion sacré a une chance de supprimer le temps de recharge de son prochain lancement."}},
["Breaks the"]={{p={"Breaks the earth beneath the target, dealing "," Nature damage to the target and an additional ","% of that damage as Nature damage to other enemies within "," yards. Creates a patch of broken earth that slows enemies inside it by ","%. After ",", the broken earth erupts in an aftershock, dealing Nature damage equal to ","% of the initial damage to all enemies within the area."},f="Brise la terre sous la cible, infligeant {1} dégâts de Nature à la cible et {2}% de ces dégâts en plus, sous forme de dégâts de Nature, aux autres ennemis situés à moins de {3} mètres. Crée une zone de terre brisée qui ralentit de {4}% les ennemis qui s'y trouvent. Après {5}, la terre brisée entre en éruption dans une réplique sismique, infligeant des dégâts de Nature égaux à {6}% des dégâts initiaux à tous les ennemis de la zone."}},
["Bring a pa"]={{p={"Bring a party member under your tutelage for ",". Whenever you cast a Discipline or Holy spell, you have a ","% chance with helpful spells, or ","% chance with harmful spells, to burn them for ","% of their total health as Holy damage and increase both your and their spell damage and healing by ","% for ",".  If cast on yourself, the spell damage and healing bonus is increased to ","%.  Only one party member can be under your tutelage at a time."},f="Prend un membre du groupe sous votre tutelle pendant {1}. Chaque fois que vous lancez un sort de Discipline ou Sacré, vous avez {2}% de chances avec les sorts bénéfiques, ou {3}% de chances avec les sorts néfastes, de le brûler pour {4}% de sa santé totale en dégâts Sacrés et d'augmenter à la fois vos dégâts et soins de sorts et les siens de {5}% pendant {6}. Si le sort est lancé sur vous-même, le bonus aux dégâts et aux soins de sorts passe à {7}%. Un seul membre du groupe peut être sous votre tutelle à la fois."}},
["Casting Ju"]={{p={"Casting Judgement reduces the casting time of your next Holy Light by "," sec."},f="Lancer Jugement réduit de {1} sec le temps d'incantation de votre prochaine Lumière sacrée."}},
["Causes all"]={{p={"Causes all enemies near the warrior to be dazed, reducing movement speed by ","% for ","."},f="Étourdit tous les ennemis proches du guerrier, réduisant leur vitesse de déplacement de {1}% pendant {2}."},
{p={"Causes all enemies near the warrior to be dazed, reducing movement speed by ","% for ","."},f="Étourdit tous les ennemis proches du guerrier, réduisant leur vitesse de déplacement de {1}% pendant {2}."}},
["Causes an "]={{p={"Causes an explosion of arcane magic around the caster, causing "," Arcane damage to all targets within "," yards."},f="Provoque une explosion d'énergie arcanique autour du lanceur, infligeant {1} points de dégâts des arcanes à toutes les cibles se trouvant à moins de {2} mètres."},
{p={"Causes an explosion of holy light around the caster, causing "," Holy damage to all targets within "," yards.  The effect also temporarily reduces your threat level against nearby targets for ","."},f="Provoque une explosion de lumière sacrée autour du lanceur, infligeant {1} points de dégâts sacrés à toutes les cibles à moins de {2} mètres. L'effet réduit aussi temporairement votre niveau de menace envers les cibles proches pendant {3}."},
{p={"Causes an explosion of holy light around the caster, causing "," Holy damage to all enemy targets within "," yards and healing all party members within "," yards for ",". Using this spell while in Shadowform damages you instead of healing you. These effects cause reduced threat."},f="Provoque une explosion de lumière sacrée autour du lanceur, infligeant {1} dégâts Sacrés à toutes les cibles ennemies situées à moins de {2} mètres et soignant tous les membres du groupe situés à moins de {3} mètres de {4}. Utiliser ce sort sous Forme d'ombre vous inflige des dégâts au lieu de vous soigner. Ces effets génèrent une menace réduite."}},
["Causes you"]={{p={"Causes you to charge an enemy, stopping its movement and interrupting any spell being cast for ","."},f="Vous fait charger un ennemi, arrêtant son déplacement et interrompant tout sort en cours d'incantation pendant {1}."},
{p={"Causes you to charge an enemy, immobilizing and interrupting any spell being cast for ","."},f="Vous charge sur un ennemi, l'immobilisant et interrompant tout sort en cours d'incantation pendant {1}."},
{p={"Causes your Fire Ward to have a ","% chance to reflect Fire spells while active."},f="Votre Gardien de feu a {1}% de chances de réfléchir les sorts de Feu tant qu'il est actif."}},
["Channel en"]={{p={"Channel energy into your demon, breaking all crowd control effects and increasing its damage dealt by ","% for ",". The demon takes ","% of its base health as damage over the duration."},f="Canalise de l'énergie dans votre démon, supprimant tous les effets de contrôle des foules et augmentant ses dégâts infligés de {1}% pendant {2}. Le démon subit {3}% de sa santé de base en dégâts pendant la durée."}},
["Chastise t"]={{p={"Chastise the target, causing "," Holy damage.  If the target is an enemy, they are disoriented for up to "," or until they take damage.  If the target is an ally, their attack and casting speed is increased by ","% for ",", increased to "," if the damage results in a critical strike.  Cannot be used on allies with less than ","% health or below level ","."},f="Châtie la cible, infligeant {1} dégâts Sacrés. Si la cible est un ennemi, elle est désorientée pendant {2} au maximum ou jusqu'à ce qu'elle subisse des dégâts. Si la cible est un allié, sa vitesse d'attaque et d'incantation est augmentée de {3}% pendant {4}, portée à {5} si les dégâts infligent un coup critique. Ne peut pas être utilisé sur des alliés ayant moins de {6}% de santé ou en dessous du niveau {7}."}},
["Command yo"]={{p={"Command your pet to intimidate the target on the next successful melee attack, stunning the target for ",", and increasing the pet's threat generation by ","% for ","."},f="Ordonne à votre familier d'intimider la cible lors de sa prochaine attaque de mêlée réussie, l'étourdissant pendant {1} et augmentant la menace générée par le familier de {2}% pendant {3}."}},
["Commands y"]={{p={"Commands your pet to instantly attack for ","% of its Attack Power. Can only be used after the Hunter lands a critical strike on the target."},f="Ordonne à votre familier d'attaquer instantanément pour {1}% de sa puissance d'attaque. Ne peut être utilisé qu'après un coup critique du chasseur sur la cible."}},
["Consumes a"]={{p={"Consumes a Rejuvenation or Regrowth effect on a friendly target to instantly heal them an amount equal to 12 sec. of Rejuvenation or 18 sec. of Regrowth."},f="Consomme un effet de Régénération ou de Rétablissement sur une cible alliée pour la soigner instantanément d'un montant égal à 12 sec. de Régénération ou 18 sec. de Rétablissement."},
{p={"Consumes a Rejuvenation or Regrowth effect on a friendly target to instantly heal them an amount equal to "," sec. of Rejuvenation or "," sec. of Regrowth."},f="Consomme un effet de Récupération ou de Rétablissement sur une cible amie pour la soigner instantanément d'un montant égal à {1} sec. de Récupération ou {2} sec. de Rétablissement."}},
["Creates a "]={{p={"Creates a holy Lightwell near the priest.  Members of your raid or party can click the Lightwell to restore "," health over ",".  Being attacked cancels the effect.  Lightwell lasts for "," or 5 charges."},f="Crée un Puits de lumière sacré près du prêtre. Les membres du raid ou du groupe peuvent cliquer sur le puits pour restaurer {1} points de vie sur {2}. Être attaqué annule l'effet. Le puits dure {3} ou 5 charges."},
{p={"Creates a violent storm in the area surrounding the caster, causing "," Nature damage to all nearby enemies every "," sec, and reducing the attack speed of all nearby enemies by ","%.  Lasts ","."},f="Crée une violente tempête autour du lanceur, infligeant {1} points de dégâts de nature à tous les ennemis proches toutes les {2} sec. et réduisant leur vitesse d'attaque de {3}%. Dure {4}."},
{p={"Creates a cloud of thick smoke in "," yards around you for ",". All targets inside the smoke have a ","% reduced chance of being hit by attacks and spells for the duration."},f="Crée un nuage de fumée épaisse dans un rayon de {1} mètres autour de vous pendant {2}. Toutes les cibles dans la fumée ont {3}% de chances en moins d'être touchées par des attaques et des sorts pendant la durée."}},
["Critically"]={{p={"Critically healing an ally applies Daybreak for ",". When the ally takes damage, Daybreak is consumed to heal them for ","."},f="Soigner un allié par un coup critique applique Point du jour pendant {1}. Lorsque l'allié subit des dégâts, Point du jour est consommé pour le soigner de {2}."}},
["Crusader S"]={{p={"Crusader Strike deals an additional ","% damage and Zeal increases your attack and casting speed by an additional ","% per stack.Holy Strike infuses you with Holy Might, increasing your Strength by ","% for ","."},f="Frappe du croisé inflige {1}% de dégâts supplémentaires et Zèle augmente votre vitesse d'attaque et d'incantation de {2}% supplémentaires par cumul.\nFrappe sacrée vous insuffle la Puissance sacrée, augmentant votre Force de {3}% pendant {4}."},
{p={"Crusader Strike has a ","% chance to reset the cooldown of your Holy Shock.  In addition, the healing effect of your Holy Strike is increased by ","% and benefits from an additional ","% of your healing power."},f="Frappe du croisé a {1}% de chances de réinitialiser le temps de recharge de votre Horion sacré. De plus, l'effet de soins de votre Frappe sacrée est augmenté de {2}% et bénéficie de {3}% supplémentaires de votre puissance de soins."}},
["Damage tak"]={{p={"Damage taken while in Moonkin Form has a ","% chance to enrage you, granting a ","% chance to avoid interruption caused by damage while casting and regenerating ","% of your maximum mana per second for ",". This effect can only trigger once every "," seconds."},f="Les dégâts subis sous Forme de sélénien ont {1}% de chances de vous enrager, vous accordant {2}% de chances d'éviter l'interruption causée par les dégâts pendant l'incantation et vous faisant récupérer {3}% de votre mana maximum par seconde pendant {4}. Cet effet ne peut se déclencher qu'une fois toutes les {5} secondes."}},
["Damaging a"]={{p={"Damaging a target afflicted by Insect Swarm with Wrath refunds ","% of its mana cost.\n\nStarfire has a ","% increased chance to critically strike against targets affected by Moonfire."},f="Infliger des dégâts avec Colère à une cible affligée par Essaim d'insectes rembourse {1}% de son coût en mana.\n\nFeu stellaire a {2}% de chances supplémentaires d'infliger un coup critique contre les cibles affectées par Eclat lunaire."}},
["Decreases "]={{p={"Decreases the cooldown of your Disarm ability by "," secs."},f="Réduit de {1} sec. le temps de recharge de votre capacité Désarmement."},
{p={"Decreases the cooldown of your Hammer of Justice spell by "," sec."},f="Réduit de {1} sec. le temps de recharge de votre sort Marteau de la justice."},
{p={"Decreases the cooldown of your Judgement spell by "," sec."},f="Réduit de {1} sec. le temps de recharge de votre sort Jugement."},
{p={"Decreases the mana lost per point of damage taken when Mana Shield is active by ","%."},f="Réduit de {1}% le mana perdu par point de dégâts subi lorsque Bouclier de mana est actif."}},
["Deepens th"]={{p={"Deepens the target's open wound, dealing damage equal to ","% of melee Attack Power and causing the target to bleed for ","% of that damage over ",". Can only be used after critically striking the target. Using this ability from the target's sides increases its damage by ","%."},f="Approfondit la blessure ouverte de la cible, infligeant des dégâts égaux à {1}% de la puissance d'attaque de mêlée et faisant saigner la cible pour {2}% de ces dégâts pendant {3}. Ne peut être utilisé qu'après un coup critique sur la cible. Utiliser cette capacité depuis les côtés de la cible augmente ses dégâts de {4}%."}},
["Dodging an"]={{p={"Dodging an attack while in Bear or Dire Bear Form imbues you with the spirit of the Ancients, generating "," Rage per second for ",". This effect can only occur once every "," seconds.  While in Cat Form, periodic ticks of your Bleed effects restore "," Energy."},f="Esquiver une attaque sous Forme d'ours ou d'ours redoutable vous imprègne de l'esprit des Anciens, générant {1} points de rage par seconde pendant {2}. Cet effet ne peut survenir qu'une fois toutes les {3} secondes. Sous Forme de félin, les effets périodiques de vos saignements restituent {4} points d'énergie."}},
["Draw upon "]={{p={"Draw upon frost leylines, becoming frozen in place, and launch icicles at the enemy, dealing "," Frost damage every "," for ",".  Damage taken has a high chance to shatter your icy prison, dealing ","% of your base health as Frost damage to you.  Cancelling the effect early will not remove the freeze effect."},f="Puise dans les lignes de force du givre, vous figeant sur place, et lance des stalactites sur l'ennemi, infligeant {1} dégâts de Givre toutes les {2} pendant {3}. Les dégâts subis ont de fortes chances de briser votre prison de glace, vous infligeant {4}% de votre santé de base en dégâts de Givre. Annuler l'effet prématurément ne supprime pas l'effet de gel."}},
["Finishing "]={{p={"Finishing move that causes damage over time.  Damage increases per combo point:\n   1 point  : 42 damage over ",".\n   2 points: 66 damage over ",".\n   3 points: 90 damage over ",".\n   4 points: 114 damage over ",".\n   5 points: 138 damage over ","."},f="Coup de grâce infligeant des dégâts sur la durée. Les dégâts augmentent par point de combo :\n   1 point  : 42 dégâts sur {1}.\n   2 points : 66 dégâts sur {1}.\n   3 points : 90 dégâts sur {1}.\n   4 points : 114 dégâts sur {1}.\n   5 points : 138 dégâts sur {1}."},
{p={"Finishing move that causes damage per combo point and converts each extra point of energy into "," additional damage.  Damage is increased by your Attack Power.\n   1 point  : 50-66 damage\n   2 points: 86-102 damage\n   3 points: 122-138 damage\n   4 points: 158-174 damage\n   5 points: 194-210 damage\n"},f="Coup de grâce infligeant des dégâts par point de combo et convertissant chaque point d'énergie supplémentaire en {1} dégâts additionnels. Les dégâts sont augmentés par votre puissance d'attaque.\n   1 point  : 50-66 dégâts\n   2 points : 86-102 dégâts\n   3 points : 122-138 dégâts\n   4 points : 158-174 dégâts\n   5 points : 194-210 dégâts"},
{p={"Finishing move that increases the effectiveness and the chance to apply poisons to your target by ","%.  Lasts longer per combo point:\n   "," point  : "," seconds\n   "," points: "," seconds\n   "," points: "," seconds\n   "," points: "," seconds\n   "," points: "," seconds"},f="Un coup final qui augmente l'efficacité et les chances d'appliquer des poisons sur votre cible de {1}%. Dure plus longtemps par point de combo :\n   {2} point : {3} secondes\n   {4} points : {5} secondes\n   {6} points : {7} secondes\n   {8} points : {9} secondes\n   {10} points : {11} secondes"}},
["Fly into a"]={{p={"Fly into a frenzy, increasing your attack speed by ","% and spell casting speed by ","% for ",".  While under this effect, your melee critical strikes increase the attack and spell casting speed of all party members within "," yards by ","% for ","."},f="Vous entrez dans une frénésie, augmentant votre vitesse d'attaque de {1}% et votre vitesse d'incantation de {2}% pendant {3}. Sous cet effet, vos coups critiques de mêlée augmentent de {5}% la vitesse d'attaque et d'incantation de tous les membres du groupe situés à moins de {4} mètres pendant {6}."}},
["Gives the "]={{p={"Gives the Gift of the Wild to the target's party, increasing armor by ",", all attributes by "," and all resistances by "," for ","."},f="Accorde le Don du fauve au groupe de la cible, augmentant l'armure de {1}, toutes les caractéristiques de {2} et toutes les résistances de {3} pendant {4}."},
{p={"Gives the Paladin a chance to deal additional Holy damage equal to ","% of melee damage.  Only one Seal can be active on the Paladin at any one time.  Lasts ",".\n\nUnleashing this Seal's energy will judge an enemy, instantly causing "," Holy damage, "," if the target is stunned or incapacitated. This damage is increased by ","% of your attack power."},f="Donne au paladin une chance d'infliger des dégâts Sacrés supplémentaires égaux à {1}% des dégâts de mêlée. Un seul Sceau peut être actif à la fois sur le paladin. Dure {2}.\n\nLibérer l'énergie de ce Sceau juge un ennemi, infligeant instantanément {3} dégâts Sacrés, ou {4} si la cible est étourdie ou incapable d'agir. Ces dégâts sont augmentés de {5}% de votre puissance d'attaque."},
{p={"Gives the Paladin's damaging melee attacks a chance to reduce the target's damage dealt by ","% for ",". Only affects targets of level "," or lower."},f="Donne aux attaques de mêlée du paladin une chance de réduire de {1}% les dégâts infligés par la cible pendant {2}. N'affecte que les cibles de niveau {3} ou inférieur."},
{p={"Gives the target of your Lay on Hands spell a ","% bonus to their armor value from items for ",".  In addition, the cooldown for your Lay on Hands spell is reduced by "," min."},f="Donne à la cible de votre sort Imposition des mains un bonus de {1}% à sa valeur d'armure provenant des objets pendant {2}. De plus, le temps de recharge de votre sort Imposition des mains est réduit de {3} min."}},
["Gives you "]={{p={"Gives you a ","% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by ","%."},f="Vous donne {1}% de chances d'entrer en état de Lucidité après qu'un sort de dégâts touche une cible. L'état de Lucidité réduit le coût en mana de votre prochain sort de dégâts de {2}%."},
{p={"Gives you ","% chance to gain "," Rage when you shapeshift into Bear and Dire Bear Form or "," Energy when you shapeshift into Cat Form."},f="Vous donne {1}% de chances de gagner {2} points de rage lorsque vous prenez la Forme d'ours ou d'ours redoutable, ou {3} points d'énergie lorsque vous prenez la Forme de félin."},
{p={"Gives you a ","% bonus to all damage you deal and decreases threat you generate by ","% for "," after dealing a critical strike from a weapon swing, spell, or ability. This effect stacks up to "," times. Threat reduction does not apply if the Paladin is under the effect of Righteous Fury."},f="Vous donne un bonus de {1}% à tous les dégâts que vous infligez et réduit la menace que vous générez de {2}% pendant {3} après avoir infligé un coup critique avec un coup d'arme, un sort ou une capacité. Cet effet se cumule jusqu'à {4} fois. La réduction de menace ne s'applique pas si le paladin est sous l'effet de Fureur vertueuse."},
{p={"Gives you a ","% melee damage bonus for "," after being the victim of a critical strike."},f="Vous donne un bonus de {1}% aux dégâts de mêlée pendant {2} après avoir été victime d'un coup critique."},
{p={"Gives you a ","% chance after blocking an attack to generate an additional attack."},f="Vous donne {1}% de chances, après avoir bloqué une attaque, de générer une attaque supplémentaire."},
{p={"Gives you a ","% chance after killing a target that yields experience or honor to allow your Mana to regenerate at a ","% rate while casting.  Lasts ","."},f="Vous donne {1}% de chances, après avoir tué une cible qui rapporte de l'expérience ou de l'honneur, de permettre à votre mana de se régénérer à {2}% pendant l'incantation. Dure {3}."},
{p={"Gives you a ","% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by ","%.  This effect can occur once every "," sec."},f="Vous donne {1}% de chances d'entrer dans un état de Clairvoyance après qu'un sort de dégâts a touché une cible. Cet état réduit de {2}% le coût en mana de votre prochain sort de dégâts. Cet effet ne peut survenir qu'une fois toutes les {3} sec."},
{p={"Gives you a ","% chance to gain a ","% bonus to your Spirit after killing a target that yields experience or critically striking a target with Mind Blast. For the duration, mana regenerates at ","% of the normal rate while casting. Lasts ","."},f="Vous donne {1}% de chances d'obtenir un bonus de {2}% à votre Esprit après avoir tué une cible qui rapporte de l'expérience ou avoir infligé un coup critique avec Attaque mentale. Pendant la durée, la mana se régénère à {3}% du rythme normal pendant l'incantation. Dure {4}."},
{p={"Gives you a ","% chance to gain an additional "," Rage anytime you get a critical strike while in Bear and Dire Bear Form and your critical strikes from Cat Form abilities that add combo points have a chance to add an additional combo point."},f="Vous donne {1}% de chances de gagner {2} points de rage supplémentaires à chaque coup critique sous Forme d'ours ou d'ours redoutable, et vos coups critiques avec les capacités de la Forme de félin qui ajoutent des points de combo ont une chance d'ajouter un point de combo supplémentaire."},
{p={"Gives you a ","% chance to gain the Focused Casting effect for "," after being hit by a melee or ranged critical strike. While active, Focused Casting prevents you from losing casting time when taking damage while casting Elemental spells."},f="Vous donne {1}% de chances d'obtenir l'effet Incantation focalisée pendant {2} après avoir subi un coup critique de mêlée ou à distance. Tant qu'il est actif, Incantation focalisée vous empêche de perdre du temps d'incantation en subissant des dégâts lors de l'incantation de sorts élémentaires."},
{p={"Gives you a ","% chance to gain the Focused Casting effect that lasts for "," after being the victim of a melee or ranged critical strike.  The Focused Casting effect prevents you from losing casting time when taking damage and increases resistance to Interrupt effects by ","%."},f="Vous donne {1}% de chances d'obtenir l'effet Incantation focalisée, qui dure {2}, après avoir été victime d'un coup critique de mêlée ou à distance. Incantation focalisée vous empêche de perdre du temps d'incantation en subissant des dégâts et augmente de {3}% la résistance aux effets d'interruption."},
{p={"Gives you a ","% chance to get an extra attack on the same target after dealing damage with your Axe or Sword."},f="Vous donne {1}% de chances d'obtenir une attaque supplémentaire sur la même cible après avoir infligé des dégâts avec votre hache ou votre épée."},
{p={"Gives you a ","% chance to stun your target for "," with a mace."},f="Vous donne {1}% de chances d'étourdir votre cible pendant {2} avec une masse."},
{p={"Gives you a ","% chance to add a combo point to your target after dodging their attack or fully resisting one of their spells."},f="Vous donne {1}% de chances d'ajouter un point de combo à votre cible après avoir esquivé son attaque ou résisté entièrement à l'un de ses sorts."},
{p={"Gives you a ","% chance to generate an additional Rage point when you deal melee damage with a weapon. The effect is doubled for two-handed weapons."},f="Vous donne {1}% de chances de générer un point de rage supplémentaire lorsque vous infligez des dégâts de mêlée avec une arme. L'effet est doublé pour les armes à deux mains."},
{p={"Gives you a ","% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability."},f="Vous donne {1}% de chances d'ajouter un point de combo supplémentaire à votre cible en utilisant Embuscade, Garrot ou Coup bas."},
{p={"Gives you a ","% chance to avoid interruption caused by damage while casting any Holy spell."},f="Vous donne {1}% de chances d'éviter l'interruption causée par les dégâts pendant l'incantation d'un sort Sacré."},
{p={"Gives you a ","% chance to avoid interruption caused by damage while casting any healing spell."},f="Vous donne {1}% de chances d'éviter l'interruption causée par les dégâts pendant l'incantation d'un sort de soins."},
{p={"Gives you a ","% chance to avoid interruption caused by damage while casting the Healing Touch, Regrowth, and Tranquility spells."},f="Vous donne {1}% de chances d'éviter l'interruption causée par les dégâts pendant l'incantation de Toucher de guérison, Rétablissement et Tranquillité."},
{p={"Gives you a ","% chance to avoid interruption caused by damage while casting your Balance spells."},f="Vous donne {1}% de chances d'éviter l'interruption causée par les dégâts pendant l'incantation de vos sorts d'Équilibre."},
{p={"Gives you a ","% chance to avoid interruption caused by damage while channeling Arcane Missiles."},f="Vous donne {1}% de chances d'éviter l'interruption causée par les dégâts pendant la canalisation de Projectiles des arcanes."}},
["Charge an "]={{p={"Charge an enemy, generate "," rage, and stun it for ",".  Cannot be used in combat."},f="Charge un ennemi, génère {1} points de rage et l'étourdit pendant {2}. Ne peut pas être utilisé en combat."},
